-- Migration V13: Seed Complete SRD Feats (2014 & 2024 Epic Boons and Origin Feats)
-- Automatically generated compendium seed with pt-BR localization

INSERT INTO player_character.feats (
    ruleset, slug, name_en, name, prerequisites, description, source
) VALUES
($$SRD_2014$$, $$grappler-2014$$, $$Grappler$$, $$Imobilizador$$, $$Força 13 ou superior$$, $$Você desenvolveu as habilidades necessárias para se agarrar com eficácia no combate corpo a corpo. Você tem vantagem em jogadas de ataque contra uma criatura agarrada por você e pode tentar imobilizá-la usando uma ação.$$, $$SRD$$),
($$SRD_2024$$, $$alert-2024$$, $$Alert$$, $$Alerta$$, $$Nível 1 (Talento de Origem)$$, $$Você ganha os seguintes benefícios.   Proficiência em Iniciativa.  Ao rolar iniciativa, você pode adicionar seu bônus de proficiência ao resultado.   Troca de Iniciativa.  Imediatamente após jogar Iniciativa, você pode trocar sua Iniciativa com a Iniciativa de um aliado voluntário no mesmo combate. Não é possível fazer a troca se você ou o aliado tem a condição &Reference[Incapacitated].    Nota do Foundry   Essa característica adiciona automaticamente o bônus à sua Iniciativa.$$, $$SRD$$),
($$SRD_2024$$, $$magic-initiate-2024$$, $$Magic Initiate$$, $$Iniciado em Magia$$, $$Nível 1 (Talento de Origem)$$, $$Você ganha os seguintes benefícios.   Dois Truques.  Você aprende dois truques da Clérigo, Druida ou Mago spell list. Seu atributo de conjuração para as magias deste talento é Inteligência, Sabedoria ou Carisma (à sua escolha ao selecionar esse talento).   Magia de 1º Círculo.  Escolha uma magia de 1º círculo da mesma lista que você selecionou para os truques deste talento. Você tem essa magia sempre preparada. Você pode conjurá-la uma vez sem um espaço de magia, e você restaura a capacidade de conjurá-la dessa maneira ao completar um Descanso Longo. Você também pode conjurar a magia usando qualquer espaço de magia que tiver.   Mudança de Magia.  Sempre que você alcança um novo nível, pode substituir uma das magias que escolheu para este talento por uma magia diferente do mesmo círculo da lista de magias escolhida.   Repetível.  Você pode adquirir este talento mais de uma vez, mas deve escolher uma lista de magias diferente a cada vez.$$, $$SRD$$),
($$SRD_2024$$, $$savage-attacker-2024$$, $$Savage Attacker$$, $$Atacante Selvagem$$, $$Nível 1 (Talento de Origem)$$, $$Você treinou para causar ataques particularmente nocivos. Uma vez por turno, ao atingir um alvo com uma arma, pode jogar os dados de dano da arma duas vezes e usar qualquer uma das jogadas contra o alvo.$$, $$SRD$$),
($$SRD_2024$$, $$skilled-2024$$, $$Skilled$$, $$Habilidoso$$, $$Nível 1 (Talento de Origem)$$, $$Você ganha proficiência em qualquer combinação de três perícias ou ferramentas à sua escolha.   Repetível.  Você pode obter este talento mais de uma vez.$$, $$SRD$$),
($$SRD_2024$$, $$ability-score-improvement-2024$$, $$Ability Score Improvement$$, $$Aumento no Valor de Atributo$$, $$Nível 4+$$, $$Talento geral (pré-requisito: nível 4+)   Aumente um valor de atributo à sua escolha em 2, ou aumente dois valores de atributos à sua escolha em 1 cada. Este talento não pode aumentar um valor de atributo acima de 20.   Repetível.  Você pode obter este talento mais de uma vez.$$, $$SRD$$),
($$SRD_2024$$, $$grappler-2024$$, $$Grappler$$, $$Imobilizador$$, $$Nível 4+$$, $$Você ganha os seguintes benefícios.   Aumento no Valor de Atributo.  Aumente seu valor de Força ou Destreza em 1, até um máximo de 20.   Agarrar e Socar.  No seu turno, ao acertar uma criatura com um ataque desarmado como parte da ação atacar, você pode usar tanto a opção dano quanto a opção agarrar. Você pode usar esse benefício apenas uma vez por turno.   Vantagem no Ataque.  Você tem vantagem em jogadas de ataque de ataque contra uma criatura &Reference[Grappled]{agarrada} por você.   Agarrador Rápido.  Você não precisa gastar deslocamento adicional para se mover quando você move uma criatura agarrada por você se a criatura for do seu tamanho ou menor.    Nota do Foundry   A vantagem não é automatizada.$$, $$SRD$$),
($$SRD_2024$$, $$archery-2024$$, $$Archery$$, $$Arquearia$$, $$Característica: Fighting Style$$, $$(Pré-requisito: Característica de Estilo de Luta)   Você ganha um bônus de +2 nas jogadas de ataque feitas com armas de combate à distância.    Nota do Foundry   Essa característica inclui um Efeito Ativo que adiciona o bônus às jogadas de ataque com armas de longo alcance.$$, $$SRD$$),
($$SRD_2024$$, $$defense-2024$$, $$Defense$$, $$Defensivo$$, $$Característica: Fighting Style$$, $$(Pré-requisito: Característica de Estilo de Luta)   Você ganha um bônus de +1 na classe de armadura enquanto estiver usando uma armadura leve, média ou pesada.    Nota do Foundry   Essa característica inclui um Efeito Ativo que concede o bônus à Classe de Armadura. Desative-o quando não estiver usando armadura.$$, $$SRD$$),
($$SRD_2024$$, $$great-weapon-fighting-2024$$, $$Great Weapon Fighting$$, $$Combate com Armas Grandes$$, $$Característica: Fighting Style$$, $$(Pré-requisito: Característica de Estilo de Luta)   Ao jogar o dano de um ataque com uma arma de combate corpo a corpo que estiver segurando com as duas mãos, você pode tratar qualquer 1 ou 2 em um dado de dano como um 3. A arma precisa ter as propriedades duas mãos ou versátil para receber este benefício.    Nota do Foundry   Esse efeito não é automatizado.$$, $$SRD$$),
($$SRD_2024$$, $$two-weapon-fighting-2024$$, $$Two Weapon Fighting$$, $$Combate com Duas Armas$$, $$Característica: Fighting Style$$, $$(Pré-requisito: Característica de Estilo de Luta)   Ao executar um ataque extra como resultado do uso de uma arma com a propriedade leve, você pode adicionar seu modificador de atributo ao dano desse ataque, caso ainda não o esteja fazendo.    Nota do Foundry   Essa característica não é automatizada. Você pode adicionar seu modificador no campo “Bônus situacional” da jogada de dano.$$, $$SRD$$),
($$SRD_2024$$, $$boon-of-combat-prowess-2024$$, $$Boon of Combat Prowess$$, $$Benção da Proeza em Combate$$, $$Nível 19+$$, $$Você ganha os seguintes benefícios.   Aumento no Valor de Atributo.  Aumente um valor de atributo, à sua escolha, em 1 até um máximo de 30.   Mira Inigualável.  Ao fazer uma jogada de ataque e errar, você pode fazer esse ataque acertar. Uma vez usado este benefício, você não poderá usá-lo novamente até o início do seu próximo turno.$$, $$SRD$$),
($$SRD_2024$$, $$boon-of-dimensional-travel-2024$$, $$Boon of Dimensional Travel$$, $$Benção da Viagem Dimensional$$, $$Nível 19+$$, $$Você ganha os seguintes benefícios.   Aumento no Valor de Atributo.  Aumente um valor de atributo, à sua escolha, em 1 até um máximo de 30.   Passos Invisíveis.  Imediatamente após usar a ação atacar ou a ação mágica, você pode se teleportar até 9 metros para um espaço desocupado que você possa ver.$$, $$SRD$$),
($$SRD_2024$$, $$boon-of-fate-2024$$, $$Boon of Fate$$, $$Benção do Destino$$, $$Nível 19+$$, $$Você ganha os seguintes benefícios.   Aumento no Valor de Atributo.  Aumente um valor de atributo, à sua escolha, em 1 até um máximo de 30.   Aprimorar Destino.  Quando você ou outra criatura a até 18 metros for bem-sucedida ou falhar em um teste de d20, você pode jogar 2d4 e aplicar o resultado obtido como um bônus ou penalidade ao resultado do d20. Uma vez usado esse benefício, você não poderá usá-lo novamente até jogar iniciativa ou terminar um descanso curto ou longo.$$, $$SRD$$),
($$SRD_2024$$, $$boon-of-irresistible-offense-2024$$, $$Boon of Irresistible Offense$$, $$Benção da Ofensa Irresistível$$, $$Nível 19+$$, $$Você ganha os seguintes benefícios.   Aumento no Valor de Atributo.  Increase your Força ou Destreza score by 1, to a maximum of 30.   Superar Defesas.  O dano contundente, perfurante e cortante que você causa sempre ignora Resistência.   Golpe Avassalador.  Ao obter 20 no d20 de uma jogada de ataque, você pode causar dano extra ao alvo igual ao valor de atributo aumentado por este talento. O tipo de dano adicional é o mesmo do tipo do ataque.    Nota do Foundry   Os efeitos desse talento não são automáticos. O dano adicional pode ser inserido no campo “Bônus situacional” da caixa de diálogo de dano.$$, $$SRD$$),
($$SRD_2024$$, $$boon-of-spell-recall-2024$$, $$Boon of Spell Recall$$, $$Benção da Magia Recordada$$, $$Nível 19+, Característica: Spellcasting$$, $$Você ganha os seguintes benefícios.   Aumento no Valor de Atributo.  Increase your Inteligência, Sabedoria ou Carisma score by 1, to a maximum of 30.   Conjuração Livre.  Sempre que você conjurar uma magia com um espaço de magia de 1° a 4° círculo, jogue . Se o resultado for igual ao círculo do espaço, o espaço não será gasto.    Nota do Foundry   Se o número for o mesmo, desmarque a opção “Consumo” ao usar a magia.$$, $$SRD$$),
($$SRD_2024$$, $$boon-of-the-night-spirit-2024$$, $$Boon of the Night Spirit$$, $$Benção do Espírito Noturno$$, $$Nível 19+$$, $$Você ganha os seguintes benefícios.   Aumento no Valor de Atributo.  Aumente um valor de atributo, à sua escolha, em 1 até um máximo de 30.   Fundir-se às Sombras.  Enquanto estiver em meia-luz ou na escuridão, você pode obter a condição &Reference[Invisible] como uma ação bônus. A condição é encerrada imediatamente após você executar uma ação, uma ação bônus ou uma reação.   Forma Sombria.  Enquanto estiver em meia-luz ou na escuridão, você tem Resistência a todos os danos, exceto radiante e psíquico.    Nota do Foundry   O efeito ativo  Benção do Espírito Noturno  desta característica inclui as resistências, mas deve ser ativado ou desativado na aba “Efeitos” da sua ficha.  A característica  Fundir-se às Sombras  inclui um efeito ativo que aplica a condição invisível.$$, $$SRD$$),
($$SRD_2024$$, $$boon-of-truesight-2024$$, $$Boon of Truesight$$, $$Benção da Visão Verdadeira$$, $$Nível 19+$$, $$Você ganha os seguintes benefícios.   Aumento no Valor de Atributo.  Aumente um valor de atributo, à sua escolha, em 1 até um máximo de 30.   Visão Verdadeira.  Você tem visão verdadeira a uma distância de até de 18 metros.    Nota do Foundry   Essa característica inclui um Efeito Ativo que concede Visão Verdadeira com um alcance de 18 metros.$$, $$SRD$$),
($$SRD_2024$$, $$tough-2024$$, $$Tough$$, $$Vigoroso$$, $$Nível 1 (Talento de Origem)$$, $$Seus pontos de vida máximos aumentam em uma quantia igual a duas vezes o seu nível de personagem, e aumentam em 2 PV adicionais a cada nível subsequente.$$, $$SRD$$),
($$SRD_2024$$, $$war-caster-2024$$, $$War Caster$$, $$Conjurador de Batalha$$, $$Nível 4, capacidade de conjurar pelo menos uma magia$$, $$Você tem vantagem em salvaguardas de Constituição para manter concentração, pode realizar os componentes somáticos empunhando armas e pode conjurar magias como ataque de oportunidade.$$, $$SRD$$)
ON CONFLICT (ruleset, slug) DO UPDATE SET
    name_en = EXCLUDED.name_en,
    name = EXCLUDED.name,
    prerequisites = EXCLUDED.prerequisites,
    description = EXCLUDED.description,
    source = EXCLUDED.source,
    updated_at = CURRENT_TIMESTAMP;
